const response = $input.first().json;

// Garante que as listas existem na resposta da API
const topGainers = response.top_gainers || [];
const topLosers = response.top_losers || [];

const combinedList = [];

// Função auxiliar para formatar os dados de cada ação
function formatStock(stock, isGainer) {
    // 1. Pega a string de porcentagem (ex: "1.23%")
    const percentStr = stock.change_percentage;

    // 2. CRIAÇÃO DO FALLBACK: Se percentStr existe, remove o '%' e converte para número. Caso contrário, usa 0.
    const numericPercent = (percentStr && percentStr.includes('%')) 
        ? parseFloat(percentStr.replace('%', '')) 
        : 0;

    return {
        ticker: stock.ticker,
        price: parseFloat(stock.price),
        change_percentage: numericPercent, // <-- Usando o valor seguro
        type: isGainer ? 'TOP' : 'FLOP'
    };
}

// Adiciona os ganhadores
topGainers.forEach(stock => combinedList.push({ json: formatStock(stock, true) }));

// Adiciona os perdedores
topLosers.forEach(stock => combinedList.push({ json: formatStock(stock, false) }));

return combinedList;

const items = $input.all();

// Os 5 Top Gainers estão nos índices 0 a 4
const topGainers = items.slice(0, 5); 

// Os 5 Top Losers estão nos índices 20 a 24 (supondo que a API retorna 20 gainers, os losers começam no índice 20)
const topLosers = items.slice(20, 25);     

// Função auxiliar para criar a tabela HTML
function formatList(title, list, isPositive) {
    let html = `<h2>${title}</h2>`;
    html += '<table border="1" cellpadding="5" cellspacing="0" style="width: 100%; border-collapse: collapse;">';
    html += '<tr style="background-color: #f2f2f2;"><th>Ação (Ticker)</th><th>Variação Percentual</th></tr>';

    // Dentro da função formatList:
list.forEach(item => {
    const color = isPositive ? 'green' : 'red';

    // Variável que pode estar undefined
    const changeValue = item.json.change_percentage; 

    // VERIFICAÇÃO DE SEGURANÇA: Se o valor for um número, formata. Caso contrário, exibe 'N/A'.
    const percent = (changeValue !== undefined && !isNaN(changeValue)) 
        ? changeValue.toFixed(2) + '%' 
        : 'N/A';


        html += `<tr>
                    <td>${item.json.ticker}</td>
                    <td style="color: ${color}; font-weight: bold;">${percent}</td>
                 </tr>`;
    });

    html += '</table>';
    return html;
}

// Monta o corpo completo do relatório
const reportHTML = `
    <h1>📊 Resumo do Mercado Diário: Top & Flop 5</h1>
    <p>Relatório gerado por automação via n8n.</p>
    ${formatList('🚀 As 5 Maiores Altas', topGainers, true)}
    <br>
    ${formatList('📉 As 5 Maiores Baixas', topLosers, false)}
    <p>Dados fornecidos pela Alpha Vantage.</p>
`;

// Retorna o resultado em um único item para o próximo nó
return [{
    json: {
        reportBody: reportHTML
    }
}];
